python3 -c "
import re, os

# Find production (non-test) code unwrap() calls
for root, dirs, files in os.walk('src'):
    for f in files:
        if f.endswith('.rs'):
            path = os.path.join(root, f)
            with open(path) as fh:
                content = fh.read()

            # Split at #[cfg(test)]
            parts = content.split('#[cfg(test)]')
            if len(parts) > 1:
                prod_code = parts[0]
            else:
                prod_code = content

            lines = prod_code.split('\n')
            for i, line in enumerate(lines, 1):
                stripped = line.strip()
                # Skip comments
                if stripped.startswith('//') or stripped.startswith('///'):
                    continue
                if '.unwrap()' in line:
                    print(f'{path}:{i}: {line.rstrip()}')
"

